"""Shared builder for src/data/study_lessons/lessons/lesson-cards.json.

The lessons index shows "35 min · 25 tasks" from this small eager sidecar. Every importer
regenerates it from ALL runtime lesson files (legacy copies excluded), so one importer never
drops another importer's lessons. Counts come only from each lesson's recorded
progress.sections checkpoints and estimated_minutes.
"""
import json
from pathlib import Path

NOTE = ("Generated by scripts/lesson_cards.py (via the lesson importers) from each lesson's "
        "progress.sections and estimated_minutes; do not edit.")


def counts_of(doc):
    cps = [c for s in (doc.get('progress') or {}).get('sections', []) for c in s['checkpoints']]
    return {'required': sum(not c['optional'] for c in cps), 'optional': sum(c['optional'] for c in cps),
            'estimated_minutes': doc.get('estimated_minutes')}


def card_counts(lessons_dir: Path):
    out = {}
    for f in sorted(lessons_dir.rglob('*_LESSON_*/*.json')):
        if 'legacy' in f.relative_to(lessons_dir).parts: continue
        doc = json.loads(f.read_bytes())
        if doc.get('progress'): out[doc['lesson_id']] = counts_of(doc)
    return out


def cards_document(counts):
    return (json.dumps({'note': NOTE, 'lessons': dict(sorted(counts.items()))}, ensure_ascii=False, indent=2) + '\n').encode()
